import functools

def solve_grundy(a, k, memo):
    """Compute Grundy number for pile of size a"""
    @functools.lru_cache(maxsize=1000000)
    def grundy(n):
        if n == 0:
            return 0
        if n in memo:
            return memo[n]

        # Compute XOR of previous moves
        options = set()

        # Option 1: Remove 1 cow (if possible)
        if n > 0:
            options.add(grundy(n - 1))

        # Option 2: If n is even, split into k piles of n/2 each
        if n > 0 and n % 2 == 0:
            half = n // 2
            g = grundy(half)
            # XOR of k copies of g
            if k % 2 == 1:
                options.add(g)
            else:
                options.add(0)

        # MEX (Minimum Excluded value)
        mex = 0
        while mex in options:
            mex += 1

        memo[n] = mex
        return mex

    return grundy(a)

def solution(input_str):
    # Parse input
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    # Find period by computing Grundy numbers up to a reasonable limit
    limit = 10000
    memo = {}
    memo[0] = 0

    grundy_seq = [0] * (limit + 1)
    for i in range(1, limit + 1):
        grundy_seq[i] = solve_grundy(i, k, memo)

    # Detect period
    period_start = None
    period_len = None

    for length in range(1, 300):
        for start in range(1, length):
            match = True
            for i in range(start, length):
                if grundy_seq[i] != grundy_seq[i + length - start]:
                    match = False
                    break
            if match:
                period_start = start
                period_len = length
                break
        if match:
            break

    # If no period found in range, use computed values directly
    def get_grundy(a):
        if a <= limit:
            return grundy_seq[a]

        # Offset within period
        if period_len is None:
            # Fallback: compute on demand
            return solve_grundy(a, k, memo)

        # Use periodic behavior
        offset = a % period_len
        if period_start == 0:
            return grundy_seq[offset]
        else:
            return grundy_seq[period_start + offset]

    # Compute XOR sum of all piles
    xor_sum = 0
    for x in a:
        xor_sum ^= get_grundy(x)

    # If XOR sum != 0, first player (Kevin) wins
    if xor_sum != 0:
        return "Kevin\n"
    else:
        return "Nicky\n"

if __name__ == "__main__":
    print(solution('1 2\n3\n'))
    print(solution('2 1\n3 4\n'))
    print(solution('6 1\n1 4 4 4 2 2\n'))
