            for neighbor in adj[node]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append(neighbor)
        return visited[t]

    # Check if s and t are already disconnected
    adj = build_graph(set())
    if not is_connected(adj):
        return '0\n0\n'

    # Try removing up to 2 edges
