    n, m, k = map(int, lines[0].split())

    adj = [[] for _ in range(n + 1)]
    for i in range(1, m + 1):
        u, v = map(int, lines[i].split())
        adj[u].append(v)
        adj[v].append(u)

    # Strategy: Try to find k cycles with required properties first
    # If can't find enough, try to find a long path

    visited = [False] * (n + 1)
    parent = [0] * (n + 1)
    depth = [0] * (n + 1)
    discovery = [0] * (n + 1)
    tree_edge_count = 0
    all_cycles = []

    def dfs_cycle(u, p):
        nonlocal tree_edge_count
        visited[u] = True
        discovery[u] = tree_edge_count
        tree_edge_count += 1
        parent[u] = p
        depth[u] = depth[p] + 1 if p else 1

        for v in adj[u]:
            if v == p:
                continue
            if visited[v]:
                # Back edge - potential cycle
                if discovery[u] > discovery[v]:
                    # u is visited later than v, skip
                    continue
                cyc = []
                curr = u
                while curr != v:
                    cyc.append(curr)
                    curr = parent[curr]
                cyc.append(v)
                all_cycles.append(cyc)
            else:
                dfs_cycle(v, u)

    # Find cycles starting from node 1
    dfs_cycle(1, 0)

    # Find cycles with unique representatives
    cycles = []
    used_representatives = [False] * (n + 1)

    for cyc in all_cycles:
        if len(cyc) >= 3 and len(cyc) % 3 != 0:
            for v in cyc:
                if not used_representatives[v]:
                    cyc_with_rep = []
                    for a in cyc:
                        if not used_representatives[a]:
                            cyc_with_rep = cyc.copy()
                            used_representatives[a] = True
                            cycles.append((cyc_with_rep, a))
                            break
