                if not used_representatives[v]:
                    used_representatives[v] = True
                    break

    # Filter and keep first k valid cycles
    valid_cycles = []
    for cyc_data in cycles:
        if len(valid_cycles) < k:
            valid_cycles.append(cyc_data[0])
        else:
            break

