        for i, cyc in enumerate(valid_cycles[:k]):
            output += f"{len(cyc)}\n"
            output += " ".join(map(str, cyc)) + "\n"
        return output.rstrip('\n')

    # Try to find a long path
    path_result = [-1, [], 0]

    # BFS-based path search
    def find_long_path():
        output_path = []
        visited_p = [False] * (n + 1)

        # Try starting from each vertex
        for start in range(1, n + 1):
            stack = [(start, [start])]
            visited_p[start] = True

            while stack:
                curr, path = stack.pop()
                output_path = path

                if len(path) >= 2:
                    path_len = len(path)

                for neighbor in adj[curr]:
                    if not visited_p[neighbor]:
                        visited_p[neighbor] = True
                        stack.append((neighbor, path + [neighbor]))

                    if len(path) >= n / k:
                        output_path = path
                        break

                if len(path) >= n / k:
                    return output_path

    path = find_long_path()

    if len(path) >= n / k:
        output = "PATH\n"
        output += f"{len(path)}\n"
        output += " ".join(map(str, path)) + "\n"
        return output.rstrip('\n')

    return "-1"
