I need to solve a CNF satisfiability problem where each variable appears in at most 2 clauses. This is a classic backtracking/constraint satisfaction problem.

The key insight is that since each variable appears at most twice, we can use backtracking with early verification. I'll build a solution that:
1. Parses the input into clauses
2. Uses backtracking to try assigning values to variables
3. Checks if assignments satisfy all clauses efficiently
4. Returns whether a valid assignment exists

```python
from typing import List

def solution(input_str: str) -> str:
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    # Parse clauses
    clauses = []
    var_occurrences = [[] for _ in range(m + 1)]  # Track clauses for each variable

    for i in range(n):
        parts = list(map(int, lines[i + 1].split()))
        k = parts[0]
        literals = parts[1:]
        clauses.append(literals)
        for lit in literals:
            var = abs(lit)
            if 1 <= var <= m:
                var_occurrences[var].append(i)

    # Check constraints: each variable appears at most once per clause
    # (Given in problem, but we can verify)
    for clause in clauses:
        lit_vars = [(abs(lit) - 1) for lit in clause]
        if len(lit_vars) != len(set(lit_vars)):
            # Variable repeats in same clause - not allowed per problem
            pass

    assignment = [0] * m
    clause_satisfied = [False] * n

    def is_satisfying():
        """Check if current assignment satisfies all clauses"""
        for clause_idx in range(n):
            satisfied = False
            for lit in clauses[clause_idx]:
                var = abs(lit) - 1
                pos = lit > 0
                if (pos and assignment[var] == 1) or (not pos and assignment[var] == 0):
                    satisfied = True
                    break
            if not satisfied:
                return False
        return True

    def backtrack(idx):
        """Try to find valid assignment using backtracking"""
        if idx == m:
            return is_satisfying()

        # Try assigning 0 (False) first
        assignment[idx] = 0
        if backtrack(idx + 1):
            return True

        # Try assigning 1 (True)
        assignment[idx] = 1
        if backtrack(idx + 1):
            return True

        return False

    if backtrack(0):
        return "YES\n" + "".join(map(str, assignment))
    else:
        return "NO"


