    given_a = list(map(int, lines[1].split()))
    arr = given_a[:]

    for i in range(len(arr), 2 * m):
        val = (101 * arr[-1] + 10007) % MOD
        arr.append(val)

    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    def build_A(n, mod):
        A = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i == j:
                    A[i][j] = 1  # stay
                else:
                    g = gcd(i + 1, j + 1)
                    A[i][j] = pow(2, g) % mod
        return A

    def mat_mul(A, B, size, mod):
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            for k in range(size):
                if A[i][k]:
                    for j in range(size):
                        if B[k][j]:
                            C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
        return C

    def mat_pow(A, p, size, mod):
        result = [[0] * size for _ in range(size)]
        for i in range(size):
            result[i][i] = 1
        base = [row[:] for row in A]
        while p > 0:
            if p & 1:
                result = mat_mul(result, base, size, mod)
            base = mat_mul(base, base, size, mod)
            p >>= 1
        return result

    if t == 0:
        res = 0
        for i in range(2 * m):
            res ^= arr[i]
        return str(res)

