def is_axis_square(grid, r, c, size, n, m):
    """Check if there's an axis-aligned square of size 'size' starting at (r, c)."""

    # Check border of top and bottom rows
    top_row = all(grid[r][idx] == '1' for idx in range(c, c + size))
    bottom_row = all(grid[r + size - 1][idx] == '1' for idx in range(c, c + size))

    # Check border of left and right columns
    left_col = all(grid[idx][c] == '1' for idx in range(r, r + size))
    right_col = all(grid[idx][c + size - 1] == '1' for idx in range(r, r + size))

    if not (top_row and bottom_row and left_col and right_col):
        return False

    # Check interior is all 0
    interior = True
    for i in range(r + 1, r + size - 1):
        for j in range(c + 1, c + size - 1):
            if grid[i][j] != '0':
                interior = False
                break
        if not interior:
            break

    if not interior:
        return False

    # Check no foreign 1 touches the square (by side or corner)
    # Check all cells in the 1-cell surrounding ring
    for dr in range(-1, 2):
        for dc in range(-1, 2):
            if dr == 0 and dc == 0:
                continue

            nr, nc = r + dr, c + dc

            # Check cells up to distance 2 from the center
            # A square of size 'size' touches cells in the range [r-1, r+size] and [c-1, c+size]
            if nr < 0 or nr >= n:
                continue
            if nc < 0 or nc >= m:
                continue

            if grid[nr][nc] == '1':
                return False

    return True


def is_diamond_square(grid, r, c, k, n, m):
    """Check if there's a diamond square with Manhattan radius k centered at (r, c)."""

    # Check perimeter (Manhattan distance == k) are all 1
    perimeter_ok = True
    for i in range(n):
        for j in range(m):
            if abs(i - r) + abs(j - c) == k:
                if grid[i][j] != '1':
                    perimeter_ok = False
                    break
        if not perimeter_ok:
            break

    if not perimeter_ok:
        return False

    # Check interior (Manhattan distance < k) are all 0
    interior_ok = True
    for i in range(n):
        for j in range(m):
            if abs(i - r) + abs(j - c) < k:
                if grid[i][j] != '0':
                    interior_ok = False
                    break
        if not interior_ok:
            break

    if not interior_ok:
        return False

    # Check no foreign 1 touches the diamond
    # Check all cells in the perimeter's surrounding ring
    for i in range(max(0, r - 2), min(n, r + k + 2)):
        for j in range(max(0, c - 2), min(m, c + k + 2)):
            if abs(i - r) + abs(j - c) == k:  # On perimeter
                continue
            if grid[i][j] != '0' or grid[i][j] == '1':
                # Check if this 1 is touching the perimeter
                for pi in range(max(0, i - 1), min(n, i + 2)):
                    for pj in range(max(0, j - 1), min(m, j + 2)):
                        if abs(pi - r) + abs(pj - c) == k:
                            # Touching!
                            return False

    return True
