            adj[u].append(v)
            edge_list.append((u, v))
        except:
            continue

    # BFS to compute shortest path distance from a source to all other nodes
    def bfs_dist(start, cities_to_check):
        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = deque([start])

        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)

        # Remove unreachable destinations from consideration if needed
        return dist

    # Precompute distances from each city
    in_dist_cache = {}

    for i in range(1, n + 1):
        dists = bfs_dist(i, list(range(1, n + 1)))
        for j in range(1, n + 1):
            if dists[j] != -1:
                in_dist_cache[(i, j)] = dists[j]

    # Find the 4 cities with maximum total distance
    max_total = -1
    best_cities = None

    # Helper to check if path exists
    path_exists = lambda a, b: in_dist_cache.get((a, b), -1) != -1

    # Try all combinations of 4 cities (C(n, 4) * 24 permutations)
    # Instead of iterating all, we can use a smarter approach
    import itertools

    for cycle in itertools.permutations(range(1, n + 1), 4):
        c1, c2, c3, c4 = cycle

        total = 0

        # d(c1, c2) + d(c2, c3) + d(c3, c4)
        if path_exists(c1, c2) and path_exists(c2, c3) and path_exists(c3, c4):
