    MOD = 1000000007

    lines = input_str.strip().split('\n')
    n = int(lines[0])
    points = []
    for i in range(1, n + 1):
        x, y = map(int, lines[i].split())
        points.append((x, y))

    def cross_product(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    def isoriented_triangle(i, mid, j):
        # Check if triangle (i, mid, j) is oriented correctly (counterclockwise)
        return cross_product(points[i], points[mid], points[j]) > 0

    def is_inside_triangle(i, mid, j, k):
        # Check if vertex k is inside triangle (i, mid, j)
        # This is used for determining if diagonal is valid
        c1 = cross_product(points[mid], points[i], points[k])
        c2 = cross_product(points[mid], points[k], points[j])
        return c1 > 0 and c2 > 0

    def is_valid_diagonal(i, j):
        # Check if diagonal from i to j is inside the polygon
        # For a simple polygon, diagonal (i, j) is valid if:
        # 1. It doesn't intersect any polygon edge (except at endpoints)
        # 2. It lies within the polygon

        # This is checked by ensuring triangle (i, j, k) is always oriented correctly
        # for all k in the middle range between i and j

        # For a diagonal (i, j) to be valid, all vertices between i and j should
        # be on the same side of the diagonal as the rest of the polygon

        for k in range(i + 1, j):
            cp = cross_product(points[i], points[j], points[k])
            if cp == 0:
                # Collinear - points should be the same since polygon is simple
                return False
            # Check orientation
            if isoriented_triangle(i, k, j) != True:
                return False

        return True

    # DP solution
    # dp[i][j] = number of triangulations using vertices from i to j
    # We need vertices from i to j to form valid triangles

    # For polygon, we can use indices 0 to n-1
    # dp[i][j] means vertices i, i+1, ..., j are considered, and we need to triangulate them

    dp = [[0] * n for _ in range(n)]

    for length in range(2, n):  # length is the distance between i and j
        for i in range(n - length + 1):
            j = i + length
            if i == j:
                dp[i][j] = 1
                continue

            # We need to count valid triangulations from vertex i to vertex j
            # For each k between i and j, we can form triangle (i, k, j) if valid

            dp[i][j] = 0
            for k in range(i + 1, j):
                # Check if triangle (i, k, j) can be formed
                # The diagonal (i, k) and (k, j) must be valid

                # First check if the diagonal (i, k) is valid
                diag_ik_valid = True
                for m in range(i + 1, k):
                    cp = cross_product(points[i], points[k], points[m])
                    if cp == 0:
                        diag_ik_valid = False
                        break

                # Check if diagonal (k, j) is valid
                diag_kj_valid = True
                for m in range(k + 1, j):
                    cp = cross_product(points[k], points[j], points[m])
                    if cp == 0:
                        diag_kj_valid = False
                        break

                # Check if triangle (i, k, j) is oriented correctly
                cp = cross_product(points[i], points[k], points[j])
                triangle_valid = cp > 0 or cp < 0  # Non-zero means not collinear

                if diag_ik_valid and diag_kj_valid and triangle_valid:
                    dp[i][j] = (dp[i][j] + dp[i][k] * dp[k][j]) % MOD

