```python
def solution(input_str):
    lines = input_str.strip().split('\n')
    s1, s2, virus = lines[0], lines[1], lines[2]
    n, m = len(s1), len(s2)
    m_virus = len(virus)

    # Build KMP transition table for virus pattern
    trans = [[0] * 26 for _ in range(m_virus + 1)]

    # Compute KMP failure function
    failure = [0] * m_virus
    j = 0
    for i in range(1, m_virus):
        while j > 0 and virus[i] != virus[j]:
            j = failure[j-1]
        if virus[i] == virus[j]:
            j += 1
        failure[i] = j

    # Compute transitions for each state and character
    for state in range(m_virus + 1):
        for c_code in range(26):
            c = chr(ord('A') + c_code)
            if state < m_virus and virus[state] == c:
                trans[state][c_code] = state + 1
            else:
                temp = state
                while temp > 0 and (temp == state or virus[temp] != c):
                    temp = failure[temp-1]
                if temp < m_virus and virus[temp] == c:
                    trans[state][c_code] = temp + 1
                else:
                    trans[state][c_code] = 0

    # DP: dp[i][j][k] = max LCS length using s1[:i] and s2[:j] with virus state k
    INF = -1
    dp = [[[INF] * (m_virus + 1) for _ in range(m + 1)] for _ in range(n + 1)]

    # Track which state we came from for reconstruction
    parent = [[[None for _ in range(m + 1)] for _ in range(n + 1)] for _ in range(m_virus + 1)]

    dp[0][0][0] = 0

    for i in range(n + 1):
        for j in range(m + 1):
            for k in range(m_virus + 1):
                if dp[i][j][k] == INF:
                    continue

                # Option 1: Skip s1[i] (advance i)
                if i < n:
                    if dp[i][j][k] >= dp[i + 1][j][k]:
                        dp[i + 1][j][k] = dp[i][j][k]
                        parent[i + 1][j][k] = (k, None)

                # Option 2: Skip s2[j] (advance j)
                if j < m:
                    if dp[i][j][k] >= dp[i][j + 1][k]:
                        dp[i][j + 1][k] = dp[i][j][k]
                        parent[i][j + 1][k] = (k, None)

                # Option 3: Take matching character s1[i] == s2[j]
                if i < n and j < m and s1[i] == s2[j]:
                    nk = trans[k][ord(s1[i]) - ord('A')]
                    if nk < m_virus:  # Don't complete the virus pattern
                        dl = dp[i][j][k] + 1
                        if dl > dp[i + 1][j + 1][nk]:
                            dp[i + 1][j + 1][nk] = dl
                            parent[i + 1][j + 1][nk] = (nk, s1[i])

    # Find maximum LCS length across all virus states
    max_len = 0
    for k in range(m_virus + 1):
        if dp[n][m][k] > max_len:
            max_len = dp[n][m][k]

    if max_len <= 0:
        return '0'

    # Reconstruct the answer
    result = []
    i, j, k = n, m, 0

    while i > 0 or j > 0:
        p = parent[i][j][k]
        if p is None:
            break

        p_k, action = p
        if action is None:
            # Skip action
            if i > 0:
                i -= 1
            else:
                j -= 1
            k = p_k
        else:
            # Take action (matching character)
            result.append(action)
            i -= 1
            j -= 1
            k = p_k

    result.reverse()
    return ''.join(result)


# Test the solution
