    def check_selected(selected):
        message_counts = [0] * n
        for i in selected:
            for j in range(n):
                if contacts[i][j] == '1':
                    message_counts[j] += 1
        return all(message_counts[j] != targets[j] for j in range(n))

    def backtrack(idx, selected, temp_counts):
        if len(selected) == n:
            return check_selected(selected)

        # Try excluding employee idx
        if backtrack(idx + 1, selected, temp_counts):
            return True

        # Try including employee idx with pruning
        counts_valid = True
        for j in range(n):
            if temp_counts[j] + (1 if contacts[idx][j] == '1' else 0) > targets[j]:
                counts_valid = False
                break

        if counts_valid:
            for j in range(n):
                temp_counts[j] += (1 if contacts[idx][j] == '1' else 0)
            selected.append(idx)
            if backtrack(idx + 1, selected, temp_counts):
                return True
            selected.pop()
            for j in range(n):
                temp_counts[j] -= (1 if contacts[idx][j] == '1' else 0)

        return False

    # We need to find any valid subset, including empty set
    # Empty set always valid since all targets >= 0 and if all 0, employee receives 0 messages but empty set gives 0 to all
    # Wait, empty set means no messages sent, but everyone receives 0 messages, and if all targets are 0, then Igor wins
    # So empty set is not valid when all targets are 0

    result = None

    def backtrack2(idx, selected, temp_counts):
        nonlocal result
        if result is not None:
            return

        if idx == n:
            if check_selected(selected):
                result = selected.copy()
                return
            return

        # Try excluding employee idx
        backtrack2(idx + 1, selected, temp_counts)
        if result is not None:
            return

        # Try including employee idx
        selected.append(idx)
        # Check immediately if valid
        valid = True
        for j in range(n):
            if temp_counts[j] + (1 if contacts[idx][j] == '1' else 0) == targets[j]:
                valid = False
                break
        if valid:
            for j in range(n):
                temp_counts[j] += (1 if contacts[idx][j] == '1' else 0)
            backtrack2(idx + 1, selected, temp_counts)
        if result is not None:
            return
        selected.pop()
        for j in range(n):
            temp_counts[j] -= (1 if contacts[idx][j] == '1' else 0)

    temp_counts = [0] * n
    backtrack2(0, [], temp_counts)

    if result is not None:
        return str(len(result)) + '\n' + ' '.join(map(str, [x + 1 for x in result]))
    else:
        return "-1"
