import math

def sq_dist(p, q):
    """Squared Euclidean distance between two 3D points"""
    return (p[0]-q[0])**2 + (p[1]-q[1])**2 + (p[2]-q[2])**2

def dist(p, q):
    """Euclidean distance between two 3D points"""
    return math.sqrt(sq_dist(p, q))

def dot(a, b):
    """Dot product of two 3D vectors"""
    return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]

def sphere_from_3points(p1, p2, p3):
    """Return (center, radius) for sphere passing through 3 non-collinear points"""
    v12 = (p2[0]-p1[0], p2[1]-p1[1], p2[2]-p1[2])
    v13 = (p3[0]-p1[0], p3[1]-p1[1], p3[2]-p1[2])

    v12_norm = sq_dist(p2, p1)
    v13_norm = sq_dist(p3, p1)
    v12_v13 = v12[0]*v13[0] + v12[1]*v13[1] + v12[2]*v13[2]

    det = 2 * (v12_norm * v13_norm - v12_v13**2)

    if abs(det) < 1e-12:
        # Points are collinear, use the two farthest points
        d12 = dist(p1, p2)
        d13 = dist(p1, p3)
        d23 = dist(p2, p3)
        if d12**2 >= d13**2 and d12**2 >= d23**2:
            return sphere_from_2points(p1, p2, p3)
        else:
            if d13**2 >= d12**2 and d13**2 >= d23**2:
                return sphere_from_2points(p1, p3)
            else:
                return sphere_from_2points(p2, p3)

    A = [[v12_norm, v12_v13, 0], [v12_v13, v13_norm, 0], [1, 0, 0]]
    b = [v12_norm/2, v13_norm/2, 1]

    center = solve_3x3(A, b)
    center = p1 + (center[0] * v12 + center[1] * v13)

    return center, dist(center, p1)

def sphere_from_3points_direct(p1, p2, p3):
    """Find circumcenter of triangle in 3D using barycentric coordinates"""
