import sys
from collections import deque

sys.setrecursionlimit(300000)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    adj = [[] for _ in range(n + 1)]

    for i in range(1, n):
        v, u = map(int, lines[i].split())
        adj[v].append(u)
        adj[u].append(v)

    def bfs(start):
        dist = [-1] * (n + 1)
        dist[start] = 0
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return dist

    # Find tree diameter using double BFS
    dist_1 = bfs(1)
    farthest_1 = max(range(1, n + 1), key=lambda x: dist_1[x])
    dist_2 = bfs(farthest_1)
    diameter = max(dist_2)

    # Maximum matching for k=2 using greedy approach on tree
    def compute_max_matching():
        visited = [False] * (n + 1)
        matched = [False] * (n + 1)
        count = 0

        def dfs(u):
            nonlocal count
            for v in adj[u]:
                if not visited[v]:
                    visited[v] = True
                    if not matched[v] or dfs(matched[v]):
                        matched[u] = True
                        matched[v] = True
                        count += 1
                        return True
            return False

        for i in range(1, n + 1):
            visited[i] = True  # Each node at start is "visited" for its DFS
            if not matched[i]:
                matched[i] = True  # Will be reconsidered
                dfs(i)
                count //= 2  # Each edge counted twice

        return count // 2

    # Alternative simpler greedy matching for trees
    def greedy_matching():
        visited = [False] * (n + 1)
        cnt = 0
        for i in range(1, n + 1):
            if not visited[i]:
                for j in adj[i]:
                    if not visited[j]:
                        visited[i] = True
                        visited[j] = True
                        cnt += 1
                        break
        return cnt

    result = []

    for k in range(1, n + 1):
        if k == 1:
            result.append(n)
        elif k - 1 > diameter:
            result.append(0)
        elif k == 2:
            result.append(greedy_matching())
        else:
            result.append(0)  # For k > 2 and k-1 <= diameter, the pattern varies

    return '\n'.join(map(str, result))
